import { z } from "zod";
const zVideoProps = z.object({
    src: z.string().url(),
    loop: z.boolean().default(false),
    autoPlay: z.boolean().default(false),
    label: z.string().optional(),
    caption: z.string().optional(),
    size: z.enum(["s", "m", "l"]).default("m"),
    width: z.number().optional(),
    height: z.number().optional(),
    aspect: z.string().optional(),
    group: z.string().or(z.literal(false)).optional(),
});
export function VideoWidget(define) {
    return define("Video")
        .props(zVideoProps)
        .shared({
        val: z.number(),
        played: z.number(),
        playing: z.boolean(),
    })
        .defaults(() => ({ val: 0, played: 0, playing: false }))
        .userEvents({
        pause: [z.literal(true), false],
        play: [z.literal(true), false],
    })
        .methods({
        seekTo: (cmd, [time]) => cmd("seekTo", [time]),
        play: (cmd) => cmd("play"),
        pause: (cmd) => cmd("pause"),
    })
        .render((props) => ({
        id: props.id,
        label: props.label,
        caption: props.caption,
        size: props.size,
        src: props.src,
        loop: props.loop,
        autoPlay: props.autoPlay,
        width: props.width,
        height: props.height,
        aspect: props.aspect,
        group: props.group,
    }));
}
